class Solution {
    private boolean isVowel(char c) {
        return "aeiou".indexOf(c) >= 0;
    }

    public int maxVowels(String s, int k) {
        int cnt = 0;
        for (int i = 0; i < k; i++) {               // 第一个窗口
            if (isVowel(s.charAt(i))) cnt++;
        }
        int best = cnt;
        for (int i = k; i < s.length(); i++) {      // 窗口右移一格
            if (isVowel(s.charAt(i))) cnt++;        // 进来 s[i]
            if (isVowel(s.charAt(i - k))) cnt--;    // 出去 s[i-k]
            best = Math.max(best, cnt);
        }
        return best;
    }
}

