public:
    int maxVowels(string s, int k) {
        int cnt = 0;
        for (int i = 0; i < k; i++) {               // 第一个窗口
            cnt += isVowel(s[i]);
        }
        int best = cnt;
        for (int i = k; i < (int)s.size(); i++) {   // 窗口右移一格
            cnt += isVowel(s[i]) - isVowel(s[i - k]);   // 进来 s[i]，出去 s[i-k]
            best = max(best, cnt);
        }
        return best;
    }
};

